import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"联系人与收信规则","description":"","frontmatter":{},"headers":[],"relativePath":"guide/contacts-rules.md","filePath":"guide/contacts-rules.md","lastUpdated":0}`),a={name:`guide/contacts-rules.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="联系人与收信规则" tabindex="-1">联系人与收信规则 <a class="header-anchor" href="#联系人与收信规则" aria-label="Permalink to “联系人与收信规则”">​</a></h1><h2 id="联系人" tabindex="-1">联系人 <a class="header-anchor" href="#联系人" aria-label="Permalink to “联系人”">​</a></h2><p>联系人页支持手动新增、编辑、删除和搜索姓名或邮箱地址，并按来源筛选：</p><ul><li>手动添加。</li><li>已发送邮件中自动发现。</li><li>已接收邮件中自动发现。</li></ul><p>写信时可以使用联系人补全。自动发现只保存通信所需的地址信息，不代表对方已被加入白名单。</p><h2 id="个人发件人白名单" tabindex="-1">个人发件人白名单 <a class="header-anchor" href="#个人发件人白名单" aria-label="Permalink to “个人发件人白名单”">​</a></h2><p>“账号设置 → 邮件”中的白名单用于信任特定发件地址或域名。命中的来信会跳过垃圾邮件分类并直接进入收件箱；它不会共享联系人，也不会授予对方访问邮箱或代替用户发信的权限。</p><p>可以填写完整邮箱地址，或填写页面支持的域名形式（例如 <code>@example.com</code>）。只添加确实信任的范围；直接放行整个域名会影响该域名下所有发件人。若需要让另一位本站用户查看邮件，应使用<a href="/nodemail-docs/guide/sharing-transfer-cleanup">邮箱共享</a>。</p><h2 id="创建收信规则" tabindex="-1">创建收信规则 <a class="header-anchor" href="#创建收信规则" aria-label="Permalink to “创建收信规则”">​</a></h2><p>在“管理 → 收信规则”创建规则，填写名称、可选描述、匹配方式、条件、动作和启用状态。一个规则可要求全部条件成立，也可要求任一条件成立。</p><p>条件支持：</p><table tabindex="0"><thead><tr><th>字段</th><th>可用判断</th></tr></thead><tbody><tr><td>发件人、收件人、抄送、回复地址、主题、正文、汇总邮件头</td><td>包含、不包含、等于</td></tr><tr><td>是否有附件</td><td>是、否</td></tr><tr><td>邮件大小</td><td>大于或小于指定字节数</td></tr></tbody></table><p>动作支持：</p><ul><li>添加已有标签。</li><li>移动到收件箱、归档、垃圾邮件或已删除。</li><li>标记已读或星标。</li><li>转发到已经验证的本人找回邮箱。</li><li>删除、标记垃圾邮件或发送站内通知。</li></ul><p>规则引用的标签必须属于当前用户。移动动作当前只接受上述系统文件夹，不支持自定义文件夹。转发只允许本人已验证的找回邮箱，防止规则被用来把邮件静默转给陌生地址。“汇总邮件头”会把发件人、收件人、抄送、回复地址和主题合并后匹配，不支持指定任意原始 Header 名称。</p><h2 id="顺序与启停" tabindex="-1">顺序与启停 <a class="header-anchor" href="#顺序与启停" aria-label="Permalink to “顺序与启停”">​</a></h2><p>规则按优先级和创建顺序执行。先用范围较窄的条件测试，再逐步增加动作。临时排查时可以停用，不必删除；规则列表会显示条件、动作和启用状态。</p><p>多个规则可能同时命中。创建“移动”和“删除”等组合前，用专用测试邮件验证最终文件夹、标签、通知和转发结果。</p><h2 id="排查规则没有生效" tabindex="-1">排查规则没有生效 <a class="header-anchor" href="#排查规则没有生效" aria-label="Permalink to “排查规则没有生效”">​</a></h2><ol><li>确认规则已启用。</li><li>检查“全部条件”与“任一条件”是否选对。</li><li>对照邮件确认发件人、收件人、抄送、Reply-To 和主题的真实值；“汇总邮件头”只匹配这些字段的合并内容。</li><li>邮件大小使用字节，不是 KB 或 MB。</li><li>确认目标标签和找回邮箱仍存在且属于当前用户，移动目标是受支持的系统文件夹。</li><li>确认规则在来信到达前已经启用，再用一封新测试邮件复查。</li></ol>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};